/* Local recovery stays account-scoped and works without a cloud connection. */
(function(){'use strict';const el=id=>document.getElementById(id),panel=document.createElement('article');panel.id='saveRecovery';panel.innerHTML='<h2>กู้เซฟสำรองในเครื่อง</h2><p>สำรองจากก่อนสร้างชีวิตใหม่ หรือนำเข้า/โหลดเซฟแทนของเดิม แยกตามบัญชีและเก็บล่าสุดหนึ่งชุด การกู้จะนำฐานข้อมูลที่อยู่ในสำรองกลับมาด้วย</p><p id="recoveryInfo"></p><button id="restoreLocalBackup">กู้สำรองล่าสุด</button><button id="downloadLocalBackup">ดาวน์โหลดสำรองล่าสุด</button><p>หากคลาวด์ขัดข้อง ให้เก็บไฟล์เซฟและฐานข้อมูลไว้ก่อน อย่าใช้เซฟคลาวด์ทับของในเครื่องจนกว่าจะตรวจวันที่และความก้าวหน้า</p><p id="recoveryStatus" role="status" aria-live="polite"></p>';el('loadStatus').before(panel);
function note(t){el('recoveryStatus').textContent=t;}
function backup(){if(!uid||!storageKey)throw Error('เข้าสู่บัญชีก่อน');const text=localStorage.getItem(storageKey+':backup');if(!text)throw Error('ยังไม่มีสำรองในเครื่องของบัญชีนี้');return text;}
function refresh(){let text;try{text=backup();const data=JSON.parse(text);el('recoveryInfo').textContent=(data.character?.name||'ยังไม่มีตัวละคร')+' • วันที่ในเกม '+data.days+' • '+data.gold+' เหรียญ';el('restoreLocalBackup').disabled=false;el('downloadLocalBackup').disabled=false;}catch(e){el('recoveryInfo').textContent=text?'สำรองอ่านไม่สำเร็จ • ดาวน์โหลดไฟล์ไว้เพื่อตรวจสอบได้':e.message;el('restoreLocalBackup').disabled=true;el('downloadLocalBackup').disabled=!text;}note('');}
el('restoreLocalBackup').onclick=()=>{try{const data=JSON.parse(backup());R.validate(data,DB);if(data.contentEdits)EvervaleEditor.validate(data.contentEdits);if(!confirm('กู้เซฟสำรองและฐานข้อมูลในสำรองแทนข้อมูลปัจจุบัน? เซฟตัวละครปัจจุบันจะถูกเก็บเป็นสำรองล่าสุดแทน'))return;EvervaleSave.load(data);note('กู้สำเร็จ • เซฟปัจจุบันเดิมถูกเก็บเป็นสำรองหากมีตัวละคร');}catch(e){note('กู้ไม่สำเร็จ: '+e.message);}};
el('downloadLocalBackup').onclick=()=>{try{const text=backup(),url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='decide-fate-player-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);note('ดาวน์โหลดสำรองแล้ว เก็บแยกจากไฟล์สำรองฐานข้อมูล');}catch(e){note(e.message);}};
new MutationObserver(()=>{if(!el('loadScreen').hidden)refresh();}).observe(el('loadScreen'),{attributes:true,attributeFilter:['hidden']});window.DecideSaveRecovery={refresh};
})();
